import {units,unitById,course,evaluation,rubric,fichaCriteria,collaborationCriteria,transferCriteria} from './course.js';
import {sessions,getSession} from './encounters.js';
import {classContent} from './class-content.js';
import {cafeExampleHtml} from './cafe-enunciacion.js';
import {lessons} from './lessons.js';
import {ficha6Phases,unit6Links,fichaPhaseLinks} from './learning-path.js';
import {manualCitation,classManualSources,referenceForClass} from './manual-sources.js';
import {lessonReferences} from './reference-sources.js';
import {perspectives} from './foundations.js';
import {resourceById,resourceHref,resourceLanguage} from './resources.js';
import {sessionMaterials,newEvidenceSource} from './workflow.js';
import {unitActivities,activityTitles,questionExamples} from './activities.js';
import {esc,fieldLabels,evidenceHtml} from './export.js';
import {hasWork,initialFicha4Question,workStatus,evidenceDraftKey,letterFields} from './state.js';
import {classHref,classForWork,resumeClass,classWork,classWriting,classEvidenceOptions,projectInputs,preparationLessons,preparationReadingOpen} from './classroom.js';
import {parseRoute,projectSections} from './navigation.js';
import {visualImages} from './visual-schema-data.js';
import {uiIcon} from './ui-icons.js';
import {leadSchemas,exampleSchemas,afterExampleSchemas,hasExampleSchema,topicImages,isAuthorMode} from './visual-schemas.js';

const ficha4Phases=['pasajes','argumento','revision'];
const ficha5Phases=['carta','aviso','revision'];
const sectionEnd='</div></section>';

function assessmentDetails(title,criteria,weightNote){
 return `<details class="ficha-guidance"><summary>${esc(title)} · 20 puntos</summary><p>Cada criterio vale hasta 4 puntos. ${esc(weightNote)}</p><ul>${criteria.map(([name,description])=>`<li><strong>${esc(name)}.</strong> ${esc(description)}</li>`).join('')}</ul></details>`;
}
const fichaAssessment=assessmentDetails('Cómo se evalúa esta ficha',fichaCriteria,'El promedio de las seis fichas vale el 35 % del curso.');
const collaborationAssessment=assessmentDetails('Cómo se evalúa tu participación',collaborationCriteria,'Las notas del trabajo en pareja de la semana 12 y de la prueba en trío de la semana 15 se promedian. Ese promedio vale el 25 % del curso.');
const transferAssessment=assessmentDetails('Cómo se evalúa el caso nuevo',transferCriteria,'Esta evaluación individual vale el 10 % del curso.');
function sectionStart(kind,icon,title,number){
 const modifier=kind==='teoria'?' theory-section':kind==='actividad'?' activity-section':'';
 return `<section class="class-section${modifier}" data-class-section="${kind}" aria-labelledby="${icon}-title"><header class="class-section-head"><h2 id="${icon}-title"><span class="section-symbol">${uiIcon(icon)}</span><span class="section-title">${number}. ${title}${kind==='actividad'?'<span class="section-note">La práctica: ahora aplícalo tú</span>':''}</span></h2></header><div class="class-section-content">`;
}

// Shared field and document components keep the original notebook contracts intact.
export function createClassroomRenderer({field,button,link,resourceCard,prose,referenceNotes,evidenceForm,evidenceList,agencyHtml,agencyContextsHtml,noticeHtml,perspectiveMap,relationForm,relationDiagram}){
 const questionModel=unit=>unit===5?`<p class="caption question-example"><strong>Para comparar la carta y el aviso</strong> ${esc(questionExamples[5])} Cuando tengas las dos piezas, cita una expresión de cada texto.</p>`:[3,4].includes(unit)?`<p class="caption question-example"><strong>Pregunta común</strong> ${esc(questionExamples[unit])}</p>`:`<p class="caption question-example"><strong>Ejemplo de pregunta:</strong> «${esc(questionExamples[unit])}». Adáptalo al fragmento que elegiste.</p>`;
 const workNotice=editable=>editable?'':`<div class="work-consult-notice"><p>Modo consulta: aquí no se puede escribir. Las notas guardadas están ocultas. Continúa solo si este trabajo es tuyo.</p>${button('resume','Continuar mi trabajo para escribir')}</div>`;
 const noteFields=(state,key,names)=>names.filter(name=>state.notes[key]?.[name]?.trim()).map(name=>`<h3>${esc(key==='apertura'?({argument:'Mi lectura inicial',revision:'Mi lectura después del contraste',revisionReason:'Qué cambió y qué evidencia falta'}[name]||fieldLabels[name]):fieldLabels[name]||name)}</h3><p class="preserve">${esc(state.notes[key][name])}</p>`).join('');
 // The sidebar is the course index; the home shows only the unit in progress and how to continue it.
 function continueLink(state){
  const current=resumeClass(state);
  if(!hasWork(state))return link(classHref(current),'Comenzar la primera clase',true);
  const route=parseRoute(state.lastLocation);
  if(route.page==='proyecto'){
   const field=projectSections[route.section]||(route.section==='hito-3'?'argument':null);
   return link(state.lastLocation,'Continuar: Expediente final'+(field?' · '+esc(projectInputs[field][0]):''),true);
  }
  if(route.page==='ficha')return link(state.lastLocation,'Continuar: '+esc(activityTitles[route.unit]||'Ficha 1'),true);
  return link(classHref(current),'Continuar: '+esc(current.title),true);
 }
 function index(state,unit=null){
  const current=resumeClass(state),shown=unitById[unit||current.unit],resume=current.unit===shown.id,started=hasWork(state);
  const classes=sessions.filter(s=>s.unit===shown.id).map(s=>{const here=resume&&s.id===current.id;return `<li><a href="${classHref(s)}" data-encounter="${s.id}"${here?' aria-current="step"':''}><span>Semana ${s.week} · Clase ${s.encounter} · ${s.duration} min${here?`<b class="class-list-here">${started?'Continúas aquí':'Primera clase'}</b>`:''}</span><strong>${esc(s.title)}</strong><span aria-hidden="true">→</span></a></li>`;}).join('');
  const action=resume?`<div class="actions course-resume">${continueLink(state)}</div>`:'';
  return `<div class="class-index"><div class="page-heading"><h1>${unit?esc(shown.title):'Análisis del discurso'}</h1><p class="lead">Cada clase reúne la teoría, la actividad y sus recursos en la misma página.</p></div><section class="class-unit" aria-labelledby="class-unit-title"><p class="meta-label">Unidad ${shown.id} · Semanas ${shown.weeks[0]}–${shown.weeks[1]}</p><h2 id="class-unit-title">${esc(shown.title)}</h2>${action}${unit?`<ol class="class-list">${classes}</ol>`:''}</section><p class="course-index-note">Las seis unidades y sus 32 clases están en el índice del curso. ${button('show-index','Ir al índice del curso')}</p>${unit?link('#inicio','Volver al inicio'):''}<details class="course-information"><summary>Programa y evaluación</summary><p>${esc(course.institution)} · 32 horas de docencia, 16 de práctica y 48 autónomas.</p><p>El curso desarrolla seis fichas y un expediente final en cuatro hitos. Puedes trabajar en hojas o en el cuaderno web. Ambos formatos se revisan con los mismos criterios.</p><div class="table-wrap"><table><thead><tr><th scope="col">Componente</th><th scope="col">Evidencia</th><th scope="col">Peso</th></tr></thead><tbody>${evaluation.map(([name,weight,text])=>`<tr><th scope="row">${esc(name)}</th><td data-label="Evidencia">${esc(text)}</td><td data-label="Peso" class="numeric">${weight}%</td></tr>`).join('')}</tbody></table></div>${units.map(u=>`<h3>${esc(u.official)}</h3><ul>${u.minimums.map(([,name])=>`<li>${esc(name)}</li>`).join('')}</ul>`).join('')}</details></div>`;
 }
  const preparationFor=s=>s.preparation;
 // Sticky class bar: section shortcuts, a theory recap at hand during the activity and the save state.
 function classBar(s){
  const topics=classContent[s.id]||[],firstSentence=text=>String(text||'').match(/^[\s\S]+?[.!?](?=\s|$)/)?.[0]||String(text||'');
  const recap=topics.length?`<details class="class-recap"><summary>${uiIcon('recap')}<span class="recap-open-label">Repaso</span><span class="recap-close-label">Cerrar repaso</span></summary><div class="class-recap-panel"><p class="meta-label">Repaso de la teoría</p><ol>${topics.map(t=>`<li><strong>${esc(t.title)}.</strong> ${esc(firstSentence(t.explanation))}</li>`).join('')}</ol></div></details>`:'';
  return `<nav class="class-bar" aria-label="Partes de la clase"><div class="class-bar-links">${[['teoria','theory','Teoría'],['actividad','activity','Actividad'],['recursos','resources','Recursos']].map(([tone,icon,label])=>button('focus-section',`${uiIcon(icon)}<span>${label}</span>`,`data-section-tone="${tone}" data-target="${icon}-title"`)).join('')}</div>${recap}<span class="class-bar-status" data-save-mirror aria-hidden="true"></span></nav>`;
 }
 // The class metadata controls initial visibility, so editing a sentence cannot hide its reading.
 function asksForGuide(s){return preparationReadingOpen.has(s.id);}
 const hasConcept=text=>/\[\[[a-z-]+/.test(String(text||''));
 const glossaryHint=`<p class="glossary-hint">${uiIcon('glossary')}<span>Las palabras con subrayado punteado abren su definición del glosario.</span></p>`;
 function topicExample(s,t){return `${t.example&&!hasExampleSchema(s.id,t.title)?`<div class="theory-example"><p class="caption">Ejemplo</p><blockquote>${esc(t.example)}</blockquote><p>${esc(t.reading)}</p></div>`:''}${exampleSchemas(s.id,t.title)}${afterExampleSchemas(s.id,t.title)}`;}
 function theory(s){
  const topics=classContent[s.id]||[];
  const guide=(preparationLessons[s.id]||[]).map(i=>lessons[s.unit][i]).filter(Boolean);
  const assigned=resourceById[s.resource]?.kind==='teoria'?resourceById[s.resource]:null;
  return `${sectionStart('teoria','theory','Teoría',1)}${guide.length?`<details class="theory-reading"${asksForGuide(s,guide)?' open':''}><summary>Lectura para antes de clase</summary>${guide.some(([,text,points])=>[text,...(points||[])].some(hasConcept))?glossaryHint:''}${guide.map(([title,text,points])=>`<h3>${esc(title)}</h3><p>${prose(text)}</p>${points?.length?`<ul>${points.map(p=>`<li>${prose(p)}</li>`).join('')}</ul>`:''}${referenceNotes(lessonReferences[s.unit]?.[lessons[s.unit].findIndex(l=>l[0]===title)])}`).join('')}</details>`:''}${assigned&&s.week<15?`<div class="assigned-reading"><h3>Lectura para preparar esta clase</h3>${resourceCard(assigned,true)}</div>`:''}${topics.map(t=>`<article class="theory-topic"><h3>${esc(t.title)}</h3><p>${esc(t.explanation)}</p>${leadSchemas(s.id,t.title)}${t.notice&&!t.noticeBrief?noticeHtml(t.notice):''}${t.points?.length?`<ul>${t.points.map(p=>`<li>${prose(p)}</li>`).join('')}</ul>`:''}${t.perspectives?perspectiveMap()+`<details class="theory-reading"><summary>Explicación y ejemplo de cada autor</summary>${perspectives.map(p=>`<h4>${esc(p.author)}</h4><p>${esc(p.definition)}</p><p><strong>Ejemplo:</strong> ${esc(p.application)}</p><p class="caption">${esc(p.limit)}</p>`).join('')}</details>`:''}${t.cafeExample?cafeExampleHtml():''}${s.id==='s10-e2'?'':topicExample(s,t)}${topicImages(s.id,t.title)}${t.takeaway?`<p><strong>${esc(t.takeawayLabel||'Idea central')}:</strong> ${esc(t.takeaway)}</p>`:''}</article>`).join('')}${classManualSources[s.id]?.length?`<p class="caption manual-source">${esc(manualCitation(classManualSources[s.id]))}</p>`:''}${s.id==='s1-e2'?`<details class="theory-reading"><summary>Recordatorio para la actividad: Benveniste y Fairclough</summary>${perspectives.filter(p=>['Émile Benveniste','Norman Fairclough'].includes(p.author)).map(p=>`<h3>${esc(p.author)}</h3><p>${esc(p.summary)}</p>`).join('')}</details>`:''}${sectionEnd}`;
 }
 function compactResource(r){
  if(resourceLanguage(r)[0]!=='es')return resourceCard(r,true);
  const href=resourceHref(r);
  return `<article class="compact-reference"><h3>${esc(r.author)} · ${esc(r.title)}</h3><p>${esc(r.selection)}</p>${href?`<a href="${esc(href)}" ${href.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>Consultar ${r.format==='pdf'?'PDF':'recurso'}<span class="sr-only">: ${esc(r.title)}</span></a>`:`<p class="caption">Consulta en ejemplar o biblioteca. La explicación del curso permite realizar la actividad.</p>`}</article>`;
 }
 function resourceSection(s){
  const sources=[...new Set((classContent[s.id]||[]).flatMap(t=>t.perspectives?perspectives.map(p=>p.source):[t.source]).filter(Boolean))].map(id=>resourceById[id]).filter(r=>r&&!r.id.startsWith('guia')&&r.id!==s.resource).map(r=>referenceForClass(r,s));
  const writingSource=s.unit===2&&s.week===4?`<h3>Fuente para apoyar tu carta</h3>${compactResource(resourceById['unesco-ia'])}<p class="consult-links">Ejemplo explicado en la teoría: <a href="${esc(resourceHref(resourceById.becas))}" target="_blank" rel="noopener noreferrer">reglamento de becas, artículos 1–3</a>.</p>`:'';
  return `${sectionStart('recursos','resources','Recursos',3)}${writingSource}${s.unit===3&&!classWork(s).assessment?compactResource(resourceById[s.id==='s7-e1'?'sarayaku':'sentencia-sarayaku']):''}${sources.length?`<details class="resource-more"><summary>Para ampliar · ${sources.length} ${sources.length===1?'lectura opcional':'lecturas opcionales'}</summary>${sources.map(compactResource).join('')}</details>`:''}<p class="consult-links">Para repasar toda la unidad: <a href="#unidad/${s.unit}/observar">guía de la unidad</a></p>${sectionEnd}`;
 }
 function diagnosis(s,state,editable){
  return `<div class="class-workspace" data-work-key="apertura"><h3>Tu trabajo · Diagnóstico inicial</h3>${workNotice(editable)}<p class="caption">Sin calificación. ${editable?'Tu texto se guarda al escribir en este navegador y aparece en «Mi trabajo». ':''}La misma lectura continúa en la segunda clase.</p>${field(state,'apertura','argument','Mi lectura inicial','Anota la diferencia observada, las palabras que la muestran, dos hipótesis y los datos que faltan.',5,editable)}${s.encounter===2?field(state,'apertura','revision','Mi lectura después del contraste','Explica qué hipótesis gana o pierde apoyo y qué mantienes o corriges.',5,editable)+field(state,'apertura','revisionReason','Qué cambió y qué evidencia falta','Identifica el dato o la objeción que afecta a tu lectura.',4,editable):''}</div>`;
 }
 function records(unit,state,editable,{open=false,session=null,review=false,section=null}={}){
  const entries=state.evidence.filter(e=>e.unit===unit),draft=state.drafts[evidenceDraftKey(unit)];
  const form=evidenceForm(unit,draft?.data||newEvidenceSource(unit,state.evidence,section),editable,session?classEvidenceOptions(session):{});
  const saved=entries.length?`<div class="saved-evidence">${entries.map(e=>`<details><summary>${esc(e.locator||'Sin localizador')} · ${esc(e.source||'Documento de trabajo')}</summary>${evidenceHtml(e)}<div class="actions">${editable?button('edit-evidence','Editar evidencia',`data-id="${esc(e.id)}"`)+button('delete-evidence','Eliminar evidencia',`data-id="${esc(e.id)}"`):''}</div></details>`).join('')}</div>`:'';
  return `<section class="inline-evidence" data-ficha-stage="evidencias">${unit>1?(entries.length?'<h3>Evidencias guardadas</h3>':''):`<h3>1. Evidencias: ${review?'consulta y comprueba tus registros':'guarda lo que encuentras'}</h3>`}${saved}${entries.length||review?`<details class="evidence-entry" ${open||draft?'open':''}><summary>${unit>1?'Abrir formulario de evidencia':review?'Añadir o recuperar una evidencia si la revisión lo requiere':'Formulario de evidencia'}</summary>${form}</details>`:form}</section>`;
 }
 function fichaQuestion(unit,state,editable,sessionId=''){if(unit>1&&sessionId&&state.notes[`ficha-${unit}`]?.question?.trim())return `<details class="saved-question"><summary>Pregunta de la ficha · consultar o ajustar</summary>${field(state,`ficha-${unit}`,'question','Pregunta de la ficha',unitActivities[unit].questionHelp,3,editable)}</details>`;const help=sessionId==='s2-e1'?'Antes de transcribir, escribe qué quieres entender del episodio. Por ejemplo: «¿Cómo distingue Drexler sus propias palabras de las que atribuye a Joaquín Sabina?». Elige después un fragmento que ayude a responderla. La pregunta se guarda al escribir y puedes ajustarla más adelante.':unitActivities[unit].questionHelp;return field(state,`ficha-${unit}`,'question','Pregunta de la ficha',help,3,editable,unit===4?initialFicha4Question(state):'');}
 function fichaFields(unit,state,editable,{review=false,all=false,showArgument=false,argumentNext='',includeQuestion=true,sessionId=''}={}){
  if(unit>1)return conciseFichaFields(unit,state,editable,{review,all,showArgument,argumentNext,includeQuestion,sessionId});
  const key=`ficha-${unit}`,a=unitActivities[unit];
  const guidance={
   's2-e1':{focus:'Hoy guarda la transcripción y la pregunta. La primera explicación se escribe en la siguiente clase.',steps:[],help:'Este espacio conserva tus notas si ya las tienes. Lo retomarás en la clase de palabras, voz y cuerpo.'},
   's2-e2':{focus:'Hoy escribe tu primera explicación con las marcas que acabas de registrar. La justificación con la lectura de Caldiz se añade en la siguiente clase.',steps:[0,1,2,4,5].map(i=>a.argumentSteps[i]),help:'Escribe tu primer borrador con los conceptos ya vistos y remite a las evidencias guardadas por sus localizadores.'},
   's3-e1':{focus:'Hoy amplía el borrador de la clase anterior. Conserva ese texto y añade la justificación; la nueva respuesta completa se escribirá en la clase de revisión.',steps:[a.argumentSteps[3],'Añade al final un apartado llamado «Justificación». Relaciona tus marcas con su función posible y con otra explicación. Si usaste la teoría de la página, indica el título del apartado. Si usaste el artículo de Caldiz, indica la página.','Si detectas un error en una marca, corrige solo esa evidencia guardada. Mantén el mismo episodio y sus localizadores.'],help:'Conserva la primera explicación y añade su justificación al final del mismo borrador.'}
  }[sessionId];
  const writingSteps=guidance?.steps||a.argumentSteps;
  const question=includeQuestion?fichaQuestion(unit,state,editable):'';
  const argument=`<section class="ficha-argument" data-ficha-stage="argumento"><h3>2. Mi argumento: explica tus evidencias</h3>${guidance?`<p class="class-writing-focus">${esc(guidance.focus)}</p>`:'<p>Responde a tu pregunta usando los fragmentos que guardaste. Aquí van tus explicaciones, los conceptos de la teoría y las otras respuestas posibles.</p>'}${writingSteps.length?`<ol class="writing-steps">${writingSteps.map(text=>`<li>${esc(text)}</li>`).join('')}</ol>`:''}${field(state,key,'argument','Mi argumento',guidance?.help||a.argumentHelp,9,editable)}</section>`;
  const revision=`<section class="inline-review" data-ficha-stage="revision"><h3>3. Revisión: cuenta qué cambió</h3><ol class="writing-steps"><li>Lee tu pregunta, tus evidencias y «Mi argumento». Comprueba los puntos indicados debajo.</li><li>Compara tu explicación con otra posible y con lo que señale otro lector.</li><li>En «Interpretación revisada», escribe la respuesta que ahora puedes defender. Deja el primer texto en «Mi argumento» para poder compararlos.</li><li>En «Qué cambió y por qué», explica qué mantuviste o corregiste y qué dato o comentario te llevó a hacerlo.</li></ol>${field(state,key,'revision','Interpretación revisada',a.reviewFocus,6,editable)}${field(state,key,'revisionReason','Qué cambió y por qué','Puedes empezar así: «Antes pensaba…; al comprobar…; ahora sostengo…; todavía falta saber…». Si mantienes tu respuesta, explica por qué.',4,editable)}<p class="caption">${editable?'El texto se guarda al escribir. «Marcar revisión terminada» cambia el estado de la ficha; después puedes seguir corrigiéndola.':'Continúa tu trabajo para editar la revisión o marcarla como terminada.'}</p>${button('review','Marcar revisión terminada',`data-key="${key}" ${editable?'':'disabled'}`)}<p id="review-error" class="field-error" role="alert"></p></section>`;
  const hasArgument=!!state.notes[key]?.argument?.trim(),hasQuestion=!!state.notes[key]?.question?.trim();
  const previous=(includeQuestion?field(state,key,'question','Pregunta de la ficha',hasQuestion?'Esta es la pregunta que guardaste. Consúltala para revisar tu respuesta.':a.questionHelp,3,editable&&!hasQuestion):'')+field(state,key,'argument',hasArgument?'Mi argumento anterior':'Mi argumento (pendiente)',hasArgument?'Esta es la primera versión, con las ampliaciones que ya habías añadido. Puedes leerla y copiar fragmentos; escribe la nueva respuesta en «Interpretación revisada», debajo.':'Todavía no hay un argumento guardado. Escribe aquí tu primera explicación con sus evidencias antes de marcar la revisión como terminada.',9,editable&&!hasArgument);
  const later=`${argumentNext?`<p class="caption class-continuity">${esc(argumentNext)}</p>`:''}${hasArgument?`<details class="saved-argument"><summary>Ver mi argumento guardado</summary><p class="caption">Ya tienes una explicación guardada en esta misma ficha. Puedes consultarla o corregirla; hoy sigue los pasos de esta clase.</p>${field(state,key,'argument','Mi argumento guardado','Este texto se conserva aunque vuelvas a una clase anterior.',9,editable)}</details>`:''}`;
   return `${review?`<details${hasArgument&&hasQuestion?'':' open'}><summary>${hasArgument&&hasQuestion?'Pregunta y argumento anteriores · consulta':'Completa la pregunta y el primer argumento'}</summary>${previous}</details>`:`${question}${all||showArgument?argument:later}`}${review||all?revision+fichaAssessment:''}`;
 }
 function conciseFichaFields(unit,state,editable,{review,all,showArgument,argumentNext,includeQuestion,sessionId}){
  const key=`ficha-${unit}`,a=unitActivities[unit],guidance=classWriting[sessionId];
  const hasArgument=!!state.notes[key]?.argument?.trim(),hasQuestion=!!state.notes[key]?.question?.trim();
  const question=includeQuestion?fichaQuestion(unit,state,editable,sessionId):'';
  const instructions=all?`<details class="ficha-guidance"><summary>Orientación para esta ficha</summary><ol>${a.argumentSteps.map(text=>`<li>${esc(text)}</li>`).join('')}</ol></details>`:'';
  const argument=`<section class="ficha-argument" data-ficha-stage="argumento">${guidance?`<p class="class-writing-focus">${esc(guidance.focus)}</p>`:''}${field(state,key,'argument','Mi argumento',(guidance?.help||'Responde a tu pregunta con las evidencias guardadas.')+' Cita las evidencias y las lecturas que uses.',9,editable)}${instructions}</section>`;
  const later=`${argumentNext?`<p class="caption class-continuity">${esc(argumentNext)}</p>`:''}${hasArgument?`<details class="saved-argument"><summary>Ver mi argumento guardado</summary>${field(state,key,'argument','Mi argumento','',9,editable)}</details>`:''}`;
  const previous=`<details${hasArgument&&hasQuestion?'':' open'}><summary>${hasArgument&&hasQuestion?'Pregunta y argumento anteriores · consulta':'Completa la pregunta y el primer argumento'}</summary>${includeQuestion?field(state,key,'question','Pregunta de la ficha',hasQuestion?'':a.questionHelp,3,editable&&!hasQuestion):''}${field(state,key,'argument','Mi argumento anterior',hasArgument?'':'Escribe tu primera explicación con las evidencias guardadas.',9,editable&&!hasArgument)}</details>`;
  const revision=`<section class="inline-review" data-ficha-stage="revision">${field(state,key,'revision','Interpretación revisada',a.reviewFocus,6,editable)}${field(state,key,'revisionReason','Qué cambió y por qué',unit===5?'Nombra a tu compañero, indica qué palabras señaló cada uno y explica tu decisión.':'Indica qué corregiste o mantuviste y qué evidencia o comentario te llevó a decidirlo.',4,editable)}${button('review','Marcar revisión terminada',`data-key="${key}" ${editable?'':'disabled'}`)}<p class="caption">${editable?'La escritura se guarda automáticamente. Este botón marca que terminaste la revisión.':'Continúa tu trabajo para editar.'}</p><p id="review-error" class="field-error" role="alert"></p></section>`;
  return `${review?previous:question+(all||showArgument?argument:later)}${review||all?revision:''}`;
 }
 function projectWork(s,state,editable,work){
  if(!work.projectFields.length)return '';
  return `<section class="inline-project" data-work-key="proyecto"><h3>Tu trabajo · Expediente final</h3>${work.evidence?'':workNotice(editable)}<p class="caption">Estos campos pertenecen al mismo expediente.${editable?' Se guardan al escribir en este navegador y aparecen en «Mi trabajo».':''}</p>${work.projectFields.map(name=>{const [label,help,rows]=projectInputs[name];return field(state,'proyecto',name,label,help,rows,editable);}).join('')}${s.week===16&&s.encounter===2?`<details class="rubric"><summary>Rúbrica para la autoevaluación</summary>${rubric.map(([name,weight,text])=>`<h4>${esc(name)} · ${weight}%</h4><p>${esc(text)}</p>`).join('')}</details><div class="actions">${button('delivery','Preparar PDF de entrega','',true)}${button('json','Descargar respaldo JSON')}</div>`:''}<details><summary>Expediente y evidencias guardadas · consulta</summary>${link('#proyecto','Abrir el expediente completo')}${evidenceList(state,null,false,false)}</details></section>`;
 }
 function workspace(s,state,editable){
  const work=classWork(s);
  if(work.diagnosis)return diagnosis(s,state,editable);
  if(work.assessment){
   const notes=noteFields(state,'ficha-3',['question','argument','revision','revisionReason']);
   const savedEvidence=state.evidence.some(e=>e.unit===3)?evidenceList(state,3):'';
   const consultation=notes+savedEvidence||'<p>Si trabajaste en hojas, consulta allí los pasajes y el dato de contexto de tu ficha 3.</p>';
   return `<section class="class-workspace"><h3>Tu trabajo · Evaluación individual (Sumativa 1)</h3><p>Escribe el análisis del caso nuevo por separado y entrégalo por el medio indicado por el docente.</p>${transferAssessment}<details><summary>Consultar mi ficha 3 como preparación</summary>${consultation}</details></section>`;
  }
  return `${work.evidence?`<div class="class-workspace" data-work-key="ficha-${s.unit}"><h3>Tu trabajo · Ficha ${s.unit}</h3>${workNotice(editable)}${s.unit>1?`<p class="caption">Ficha ${s.unit} · ${editable?'La escritura se guarda automáticamente. Los fragmentos se guardan con «Añadir evidencia».':'Consulta el trabajo de esta unidad.'}</p>`:`<p class="caption">Continúa esta misma ficha durante las clases de la unidad.${editable?(s.id==='s2-e1'?' La pregunta se guarda al escribir.':' La pregunta, el argumento y la revisión se guardan al escribir.')+' Para guardar cada fragmento, completa su formulario y pulsa «Añadir evidencia». Todo aparece en «Mi trabajo».':''}</p>`}${work.review?'':fichaQuestion(s.unit,state,editable,s.id)}${records(s.unit,state,editable,{open:work.step==='analizar'&&!state.evidence.some(e=>e.unit===s.unit),session:s,review:work.review})}${fichaFields(s.unit,state,editable,{review:work.review,showArgument:work.argument,argumentNext:work.argumentNext,includeQuestion:work.review,sessionId:s.id})}${work.relations?relations(state,editable):''}</div>`:''}${projectWork(s,state,editable,work)}`;
 }
 function classPage(route,state,editable){
  const s=getSession(route.week,route.encounter),position=sessions.indexOf(s),previous=sessions[position-1],next=sessions[position+1],material=sessionMaterials(s);
  if(s.unit>1)return continuousClass(s,state,editable,previous,next);
  const work=workspace(s,state,editable).replace('<h3>','<h3 id="class-work-title">');
  const guideDownload=s.week===2?'<p class="caption"><a class="source-link" href="docs/guia-trabajo-semana-2.pdf" type="application/pdf" download="Guia de trabajo - Semana 2.pdf">Descargar guía de trabajo de la semana 2 (PDF, 2 páginas)</a></p>':'';
  return `<article class="class-page"${s.week>3?' data-simple-work':''}><div class="page-heading"><p class="meta-label">Unidad ${s.unit} · Semana ${s.week} · Clase ${s.encounter} · ${s.duration} minutos</p><h1>${esc(s.title)}</h1><section class="class-overview" aria-label="Preparación y resultado de la clase"><dl><div class="class-preparation"><dt>${uiIcon('theory')}Antes de esta clase</dt><dd>${esc(preparationFor(s))}</dd></div><div class="class-outcome"><dt>${uiIcon('activity')}Al terminar</dt><dd>${esc(s.product)}</dd></div></dl></section>${guideDownload}</div>${classBar(s)}${theory(s)}${sectionStart('actividad','activity','Actividad',2)}<div class="class-materials"><h3>Documento de análisis</h3>${material.corpus.map(id=>id==='agencia'?agencyHtml({heading:4,nextClass:s.encounter===1}):resourceCard(resourceById[id],true)).join('')}${!material.corpus.length?`<p>${s.week===8?'El docente proporciona el caso nuevo de evaluación.':'Trabaja con los documentos y segmentos de tu expediente.'}</p>`:''}</div><h3>Pasos de esta clase</h3><ol class="class-agenda">${s.agenda.map(([time,title,text])=>`<li><div class="agenda-heading"><h4>${esc(title)}</h4><span>${time} min</span></div><p>${esc(text)}</p>${s.id==='s1-e2'&&title==='Contrastar los contextos'?agencyContextsHtml():''}</li>`).join('')}</ol>${work}${sectionEnd}${resourceSection(s)}<nav class="class-pagination" aria-label="Cambiar de clase">${previous?`<a class="pager-link" href="${classHref(previous)}">Clase anterior: ${esc(previous.title)}</a>`:'<span></span>'}${next?`<a class="pager-link pager-next" href="${classHref(next)}">Siguiente clase: ${esc(next.title)}</a>`:'<a class="pager-link pager-next" href="#cuaderno">Consultar y exportar mi trabajo</a>'}</nav></article>`;
 }
 function relations(state,editable){return `<details class="optional-tool"><summary>Mapa de relaciones · opcional</summary><p class="caption">Si te ayuda a comparar las dos piezas, completa el registro y pulsa «Añadir relación». El mapa se conserva con el trabajo de la ficha 5.</p>${state.relations.map(r=>`<article><h4>${esc(r.from)} → ${esc(r.to)}</h4><p>${esc(r.evidence)}</p>${editable?button('delete-relation','Eliminar relación',`data-id="${esc(r.id)}"`):''}</article>`).join('')}${relationForm(editable)}${relationDiagram(state.relations)}</details>`;}
 function continuousClass(s,state,editable,previous,next){
  const work=classWork(s),projectOnly=s.unit!==2&&!work.evidence&&!work.assessment;
  const today=({'s4-e1':'Escribir · Define a quién diriges la carta, tu tesis y dos razones. Empieza en tus hojas o en «Borrador de mi carta».','s4-e2':'Escribir · Redacta el borrador completo. Revisa cómo nombras a los grupos y qué acciones les atribuyes.','s5-e1':'Leer al compañero · Intercambien borradores. Escribe la propuesta que entiendes y señala los pasajes que comentarás.','s5-e2':'Leer al compañero · Completa tus tres comentarios y entrégaselos al autor. Usa los comentarios recibidos para revisar tu propia carta.','s6-e1':'Revisar · Ajusta el título, los párrafos y la jerarquía visual de tu carta en papel o en un editor como Word. Registra la decisión en «Tres decisiones de revisión».','s6-e2':'Revisar · Completa «Versión final de mi carta» y «Tres decisiones de revisión», o reúne esas partes en tus hojas.','s7-e1':'En la ficha 3, marca el comienzo del pronunciamiento y el pasaje donde Sarayaku anuncia lo que hará. Si ya empezaste con la carta, retoma los dos pasajes que elegiste.',
  's7-e2':'En «Mi argumento» de la ficha 3, relaciona «estaremos atentos» con la obligación de consulta del Estado. Si sigues con la carta, usa el comentario recibido para explicar una formulación.',
  's8-e1':'Revisa el párrafo de tu ficha 3 con el dato que documentaste. En «Método y contexto documentado» del expediente, remite a esa ficha y resume cómo lo comprobaste.',
  's9-e1':'Elige una expresión del discurso de Menchú y una de cada uno de los dos pasajes de Márquez. Anota dónde aparecen.',
  's9-e2':'En «Mi argumento», explica qué significado da Menchú al premio ante su público y cómo responde Márquez a las periodistas con el ejemplo del agua.',
  's10-e1':'Amplía «Mi argumento»: explica qué aporta la voz de Davis a la respuesta de Márquez.',
  's10-e2':'Con un compañero, comprueba a quién se atribuye una idea. En «Mi revisión final», explica qué mantienes o corriges y por qué.',
  's11-e1':'Retoma el párrafo que marcaste en tu carta. Anota dónde está y qué decisión pides a la dirección. Si trabajas con otro documento, usa tu primer pasaje.',
  's11-e2':'Redacta el aviso para primer semestre y guárdalo como segunda pieza. Compáralo con la carta y escucha qué acción entiende un compañero. Si ya comparas documentos vinculados, usa tu segunda pieza.',
  's12-e2':'Con un compañero, señala las palabras que apoyan o ponen en duda tu comparación. Decide qué formulación mantienes o cambias. En «Qué cambió y por qué», registra una sola vez los aportes y tu decisión.',
  's13-e1':'Retoma un texto de una ficha anterior. Usa sus localizadores para explicar qué hacen dos tramos.',
  's13-e2':'Amplía la explicación de los mismos tramos. Describe qué cambia entre ellos y para qué sirve esa transición.',
  's14-e1':'En «Mi argumento», justifica tu lectura con las palabras del texto y examina una objeción.',
  's14-e2':'Examina cómo una respuesta modifica el diálogo. Revisa tu interpretación en la ficha 6 y lleva al expediente el hallazgo que responda a su pregunta.'}[s.id])||classWriting[s.id]?.focus||(work.review?'Revisa tu explicación con las evidencias y el comentario de otro lector.':'Continúa el análisis del documento y conserva el avance en la misma actividad.');
  const projectToday={
   's12-e1':'Si estudias cómo revisaste la carta, compara un pasaje del borrador con su versión final y retoma el comentario recibido. Si estudias el cambio de destinatario, compara la carta y el aviso. Si sigues con Sarayaku, retoma los pasajes del pronunciamiento y el dato de la sentencia. Con otro corpus, elige dos pasajes que respondan a tu pregunta. Escribe 2–3 párrafos en «Desarrollo del análisis», con una objeción y un límite. Anota las fuentes en «Referencias y atribuciones».',
   's15-e1':'Contrasta tu conclusión con el pasaje elegido. Si encuentras un contraejemplo, corrige la afirmación. Si la mantienes, explica hasta dónde llega la evidencia. Retoma un fragmento ya analizado para preparar «Actividad de enseñanza» y «Guion de defensa».',
   's15-e2':'En tu turno de 5 minutos, guía a un compañero con el fragmento que elegiste. Si usas tu aviso, pídele que compare qué se le pide a la dirección en la carta y qué se les pide a los estudiantes en el aviso. Registra en «Actividad de enseñanza» los aportes del trío y el ajuste.',
   's16-e1':'Defiende una decisión con su evidencia en tu turno. Guarda la pregunta recibida y tu respuesta en «Guion de defensa», y el ajuste previsto en «Registro de cambios».',
   's16-e2':'Completa tu defensa si corresponde. Para la segunda revisión comentada, muestra al docente una de las fichas 4 a 6 con sus versiones y el motivo del cambio que ya guardaste. Puedes usar ese ejemplo en «Autoevaluación». Comprueba tus referencias y entrega las hojas o el PDF por el canal indicado en clase.'
  }[s.id];
  const phaseLink=fichaPhaseLinks[s.id];
  const unit6Link=unit6Links[s.id];
  const classActivityLink=unit6Link?link(unit6Link[0],unit6Link[1],true):phaseLink?link('#ficha/'+s.unit+'/'+phaseLink[0],phaseLink[1],true):link(`#ficha/${s.unit}`,'Ver la actividad de la unidad',true);
  const discussion=s.id==='s10-e2'?`<details class="theory-reading class-discussion"><summary>Puesta en común · abrir después del intercambio</summary>${topicExample(s,classContent[s.id][0])}</details>`:'';
  const destination=work.assessment?`<ol class="class-agenda">${s.agenda.map(([,title,text])=>`<li><h4>${esc(title)}</h4><p>${esc(text)}</p></li>`).join('')}</ol>${workspace(s,state,editable).replace('<h3>','<h3 id="class-work-title">')}`:projectOnly?`<h3 id="class-work-title">Expediente final</h3><p>${esc(s.product)}</p>${projectToday?`<p><strong>Hoy:</strong> ${esc(projectToday)}</p>`:''}<p class="caption">Continúa el mismo expediente en tus hojas o en el cuaderno web.</p>${s.defensePlan?`<p><strong>Defensas individuales:</strong> ${s.defensePlan.slots} turnos de ${s.defensePlan.slotMinutes} minutos. Sigue el turno asignado por el docente.</p>`:''}${s.id==='s12-e1'?link('#proyecto/hito-3','Abrir el desarrollo del análisis',true):classActivityLink}`:`<h3 id="class-work-title">${esc(activityTitles[s.unit])}</h3><p><strong>Hoy:</strong> ${esc(today)}</p>${['s7-e1','s9-e1','s11-e2','s13-e1'].includes(s.id)?questionModel(s.unit):''}<p class="caption">Continúa la ficha ${s.unit} en tus hojas o en el cuaderno web.</p>${classActivityLink}${work.projectFields.length?`<p class="consult-links">${s.unit===6?'Si el hallazgo responde a la pregunta del informe, úsalo en <a href="#proyecto/analisis">Desarrollo del análisis</a>.':`Usa este avance en el <a href="${s.id==='s12-e2'?'#proyecto/hito-3':s.week===8?'#proyecto/metodo':'#proyecto/pregunta'}">expediente final</a> · ${work.projectFields.map(f=>esc(projectInputs[f][0])).join(' y ')}.`}</p>`:''}`;
  const teacher=isAuthorMode()?`<details class="teacher-agenda"><summary>Organización docente · tiempos de esta clase</summary><ol class="class-agenda">${s.agenda.map(([time,title,text])=>`<li><div class="agenda-heading"><h4>${esc(title)}</h4><span>${time} min</span></div><p>${esc(text)}</p></li>`).join('')}</ol></details>`:'';
  return `<article class="class-page" data-simple-work><div class="page-heading"><p class="meta-label">Unidad ${s.unit} · Semana ${s.week} · Clase ${s.encounter} · ${s.duration} minutos</p><h1>${esc(s.title)}</h1><section class="class-overview" aria-label="Preparación de la clase"><dl><div class="class-preparation"><dt>${uiIcon('theory')}Antes de esta clase</dt><dd>${esc(preparationFor(s))}${s.id==='s9-e1'?' <a href="#ficha/4/lecturas">Leer los dos fragmentos</a>':''}</dd></div></dl></section></div>${classBar(s)}${theory(s)}${sectionStart('actividad','activity',work.assessment?'Evaluación individual':projectOnly?'Expediente final':'Actividad de la unidad',2)}${destination}${['s12-e2','s15-e2'].includes(s.id)?collaborationAssessment:''}${discussion}${sectionEnd}${resourceSection(s)}${teacher}<nav class="class-pagination" aria-label="Cambiar de clase">${previous?`<a class="pager-link" href="${classHref(previous)}">Clase anterior: ${esc(previous.title)}</a>`:''}${next?`<a class="pager-link pager-next" href="${classHref(next)}">Siguiente clase: ${esc(next.title)}</a>`:'<a class="pager-link" href="#cuaderno">Mi trabajo</a>'}</nav></article>`;
 }
 function letterActivity(state,editable,current,returnPhase,section){
  const returnLink=returnPhase?`<a href="#ficha/5/${esc(returnPhase)}">Volver a mi ficha 5</a>`:'';
  const key='ficha-2',a=unitActivities[2],notes=state.notes[key]||{};
  const previousFields=Object.keys(notes).filter(name=>!letterFields.includes(name)&&notes[name]?.trim());
  const hasPrevious=previousFields.length||state.evidence.some(e=>e.unit===2)||state.drafts[evidenceDraftKey(2)];
  const started=letterFields.some(name=>notes[name]?.trim());
  const phase=section==='version-final'?'revision':section||(notes.letterDecisions?.trim()||notes.letterFinal?.trim()?'revision':notes.letterPeer?.trim()?'lectura':'borrador');
  const legacy=hasPrevious?`<details class="activity-work-part"><summary>Trabajo anterior sobre el reglamento</summary><p class="caption">Tus notas, evidencias y preparaciones anteriores siguen disponibles aquí y se incluyen al exportar la ficha.</p>${previousFields.map(name=>field(state,key,name,fieldLabels[name],'Puedes consultar o editar esta nota anterior.',4,editable)).join('')}${records(2,state,editable)}</details>`:'';
  const optionalAI=a.aiHelp?`<details class="ficha-guidance"><summary>Revisar con IA · opcional</summary><p>${esc(a.aiHelp)}</p></details>`:'';
  const rubric=a.rubric?`<details class="ficha-guidance"><summary>Criterios de evaluación · 10 puntos</summary><p>La carta y tu lectura de la carta del compañero reciben una sola nota individual. El puntaje se multiplica por 2 (por ejemplo, 8/10 equivale a 16/20) y cuenta una vez en el promedio de las seis fichas, que vale el 35 % del curso.</p><ul>${a.rubric.map(([label,points])=>`<li><strong>${points} puntos:</strong> ${esc(label)}</li>`).join('')}</ul></details>`:'';
  const source=resourceById['unesco-ia'];
  return `<article class="class-page ficha-page continuous-activity" data-simple-work><div class="page-heading"><p class="meta-label">Unidad 2 · Escribir y representar · Ficha 2</p><h1>${esc(activityTitles[2])}</h1><p><strong>Resultado:</strong> ${esc(a.product)}</p><p>Trabaja en hojas o en el cuaderno web.</p><p class="back-links">${returnLink||`<a href="${classHref(current)}">Volver a la clase</a>`}<a href="#semana/4/1">Consultar el apoyo para escribir</a></p></div><section class="class-materials"><h2>Tu carta y sus lectores</h2><p>${esc(a.material)}</p>${source?`<p class="consult-links"><a href="${esc(resourceHref(source))}" target="_blank" rel="noopener noreferrer">Consultar la fuente en español: ${esc(source.title)}</a></p>`:''}</section><section><h2>Una actividad en tres momentos</h2><ol class="activity-phases">${a.steps.map(([title,instructions],i)=>`<li><h3 id="${['paso-2-borrador','paso-2-lectura','paso-carta-final'][i]}" tabindex="-1">${esc(title)}</h3><p>${esc(instructions)}</p>${i===2&&returnLink&&!notes.letterFinal?.trim()?`<p class="back-links">${returnLink}</p>`:''}${i===1?`<ul>${a.argumentSteps.map(text=>`<li>${esc(text)}</li>`).join('')}</ul><p><strong>Ejemplo de comentario:</strong> ${esc(a.commentExample)}</p>`:''}</li>`).join('')}</ol><p>Identifica al autor y al revisor. Conserva ambas versiones y los comentarios recibidos. En papel, adjunta la devolución. En la web, pégala al inicio de «Tres decisiones de revisión», bajo «Comentarios recibidos», con el nombre del revisor. Después escribe tus tres decisiones.</p>${rubric}${optionalAI}</section><details class="class-workspace activity-work-part" data-work-key="${key}"${editable&&started?' open':''}><summary>Cuaderno web (opcional)</summary>${workNotice(editable)}<p class="caption">${editable?'Cada parte se guarda automáticamente al escribir. En «Mi trabajo» puedes consultar y exportar tu carta.':'Continúa tu trabajo para escribir.'}</p><details class="activity-work-part"${phase==='borrador'?' open':''}><summary>1. Escribir mi carta</summary>${field(state,key,'letterDraft',fieldLabels.letterDraft,'Empieza con destinatario, tesis y dos razones. Después desarrolla aquí el borrador completo de 350–500 palabras y anota la fuente que usaste.',12,editable)}</details><details class="activity-work-part"${phase==='lectura'?' open':''}><summary>2. Leer la carta del compañero</summary>${field(state,key,'letterPeer',fieldLabels.letterPeer,'Anota el nombre de quien escribió la carta y tu nombre como revisor. Escribe la propuesta que entiendes, copia tres pasajes y coméntalos con la guía de arriba. Comparte estos comentarios con tu compañero.',10,editable)}</details><details class="activity-work-part"${phase==='revision'?' open':''}><summary>3. Revisar mi carta</summary>${field(state,key,'letterFinal',fieldLabels.letterFinal,'Conserva aquí el texto final y el primero en «Borrador de mi carta». Para trabajar tamaños y disposición, usa la misma carta en papel o en un editor como Word; guarda esa presentación junto al trabajo.',12,editable)}${returnLink&&notes.letterFinal?.trim()?`<p class="back-links">${returnLink}</p>`:''}${field(state,key,'letterDecisions',fieldLabels.letterDecisions,'Guarda primero los comentarios recibidos con el nombre del revisor. Debajo, explica tres decisiones: pasaje inicial y final, motivo y concepto utilizado. Si una es visual, describe la disposición y lo que observó el lector. Si usaste IA, identifica la sugerencia y tu decisión.',6,editable)}${button('review','Marcar revisión terminada',`data-key="${key}" ${editable?'':'disabled'}`)}<p class="caption">El botón registra el cierre. Tus textos se guardan mientras escribes.</p><p id="review-error" class="field-error" role="alert"></p></details>${legacy}</details><p class="consult-links"><a href="#cuaderno">Consultar y exportar mi trabajo</a></p></article>`;
 }
 function priorFichaMaterials(state){
  const saved=units.filter(u=>u.id<6).map(u=>{
   const key='ficha-'+u.id;
   const notes=noteFields(state,key,u.id===2?['letterFinal','argument','revision']:['argument','revision']);
   const entries=state.evidence.filter(e=>e.unit===u.id);
   if(!notes&&!entries.length)return '';
   return `<details><summary>Ficha ${u.id} · ${esc(u.title)}</summary>${notes}${entries.map(e=>evidenceHtml(e)).join('')}</details>`;
  }).join('');
  return saved?`<details class="ficha-guidance"><summary>Consultar mis fichas anteriores</summary>${saved}</details>`:'';
 }
 function continuousActivity(unit,state,editable,current,section){
  const a=unitActivities[unit],key=`ficha-${unit}`,notes=state.notes[key]||{},hasEvidence=state.evidence.some(e=>e.unit===unit);
  const corpus=sessionMaterials(sessions.find(s=>s.unit===unit)).corpus;
  const phases=unit===3?['pasajes','contexto','revision']:unit===4?ficha4Phases:unit===5?ficha5Phases:unit===6?ficha6Phases:null;
  const writing=`<section class="ficha-argument" data-ficha-stage="argumento">${field(state,key,'argument','Mi argumento',a.argumentHelp+' Cita las lecturas que uses.',10,editable)}${unit===5?relations(state,editable):''}</section>`;
  const review=`<section class="inline-review" data-ficha-stage="revision">${field(state,key,'revision','Interpretación revisada',a.reviewFocus,6,editable)}${field(state,key,'revisionReason','Qué cambió y por qué',unit===5?'Nombra a tu compañero, indica qué palabras señaló cada uno y explica tu decisión.':'Indica qué corregiste o mantuviste y qué evidencia o comentario apoyó tu decisión.',4,editable)}${button('review','Marcar revisión terminada',`data-key="${key}" ${editable?'':'disabled'}`)}<p class="caption">La escritura se guarda automáticamente. El botón marca el cierre de la revisión.</p><p id="review-error" class="field-error" role="alert"></p></section>`;
  return `<article class="class-page ficha-page continuous-activity" data-simple-work><div class="page-heading"><p class="meta-label">Actividad de la unidad ${unit} · Ficha ${unit}</p><h1>${esc(activityTitles[unit])}</h1><p>Haz esta ficha en hojas o en el cuaderno web. Usa el formato que elijas ${unit===6?'durante las cuatro clases de la ficha':'para las tres fases'}.</p><p><strong>Resultado:</strong> ${esc(a.product)}</p><p class="back-links"><a href="${classHref(current)}">Volver a la clase</a><a href="#unidad/${unit}/observar">Consultar teoría de la unidad</a></p></div><section class="class-materials">${unit===4?'<h2 id="lecturas-ficha-4" tabindex="-1">Lecturas de Menchú y Márquez</h2>':'<h2>Documento de análisis</h2>'}<p>${esc(a.material)}</p>${corpus.map(id=>resourceCard(unit===2?{...resourceById[id],selection:'Artículos 1–3, páginas 1–2 del archivo. Consulta los artículos 8–9 (página 3 del archivo) solo si necesitas comprobar un requisito.'}:resourceById[id],true)).join('')}</section><section><h2>Cómo desarrollar la actividad</h2><p>En hojas, pon tu nombre y «Ficha ${unit}». ${unit===3?'Anota los dos pasajes y dónde encontrarlos.':unit===4?'Trabaja con la pregunta común que aparece abajo o con la que ya elegiste. Subraya o copia una expresión por pasaje y anota la autora y el inicio del párrafo.':unit===6?'Retoma tu pregunta y anota el número de la ficha anterior y la página, el párrafo o el minuto de los pasajes.':'Anota la pregunta, el fragmento y su fuente con página, párrafo o minuto.'} Usa «Mi argumento» para explicar y «Mi revisión final» para añadir la respuesta revisada y su motivo. Conserva las hojas juntas.</p>${questionModel(unit)}${unit===3?`<p><strong>Dato de contexto.</strong> La Corte dispuso que el Estado consultara previamente al pueblo ante futuros proyectos que pudieran afectar su territorio. <a href="${esc(resourceHref(resourceById['sentencia-sarayaku']))}" target="_blank" rel="noopener noreferrer">Ver el punto 3 de «Y dispone», p. 100</a>.</p><details class="ficha-guidance"><summary>Si ya empezaste con la carta u otros documentos</summary><p>Continúa en este mismo cuaderno o en tus hojas con tu pregunta y tus pasajes. Para la carta, recupera <a href="#ficha/2">el borrador y la versión final de la ficha 2</a>. Usa el comentario recibido o la consigna para explicar una decisión en «Mi argumento». Después revisa qué parte de tu explicación respalda ese dato. Si trabajabas con el aviso de la UNAE, puedes volver a <a href="${esc(visualImages['img-convocatoria'].source.url)}" target="_blank" rel="noopener noreferrer">la publicación y su resolución</a>.</p></details><p>En el <a href="#proyecto">expediente final</a> puedes remitir a la ficha 3. Las 2–4 piezas y los 6–10 segmentos corresponden al informe completo.</p>`:unit===4?'<details class="ficha-guidance"><summary>Si ya empezaste con otro texto</summary><p>Continúa con tu pregunta y tus pasajes. Al hablar de colectivos, explica a quién se nombra en tu texto. Escoge una idea citada o un punto de vista que se evoca en tus pasajes. Si el texto deja abierta su procedencia, señala qué palabras permiten reconocer ese punto de vista. Revisa tu frase con un compañero.</p></details>':unit===5?'<p>En la semana 12, clase 1, lleva esta comparación al <a href="#proyecto/hito-3">hito 3 del expediente</a> si responde a tu pregunta. Si tu pregunta trata de otro asunto, usa los pasajes que ya elegiste para investigarlo. En la clase 2 vuelves aquí para revisar la comparación con un compañero.</p>':unit===6?`<p>En la ficha 5 ya observaste a quién se dirige el aviso. Aquí puedes explicar cómo «Propuse a la carrera…» cuenta una gestión anterior y cómo «¿qué ejemplos te ayudarían?» invita a participar dentro del mismo párrafo.</p>${editable?priorFichaMaterials(state):''}`:''}<ol class="activity-phases">${a.steps.map(([title,instructions],i)=>`<li><h3${phases?` id="paso-${unit}-${phases[i]}" tabindex="-1"`: ''}>${esc(title)}</h3><p>${esc(instructions)}</p>${unit===5&&i===0?`<p><a href="#ficha/2/version-final/desde-ficha-5/${section||'carta'}">Ver mi carta de la ficha 2</a> · En hojas, busca tu versión final.</p>`:''}${unit===6&&i===3?'<p>Si el hallazgo ayuda a responder la pregunta de tu informe, ajusta la afirmación correspondiente en <a href="#proyecto/analisis">Desarrollo del análisis</a>. Remite a la cita si ya figura allí. En la semana 15 puedes usar el mismo fragmento para enseñar o defender tu interpretación.</p>':''}</li>`).join('')}</ol><details class="ficha-guidance"><summary>${unit===3?'Pistas para explicar el pronunciamiento':'Qué incluir en la explicación'}</summary><ul>${a.argumentSteps.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>${fichaAssessment}</section><details class="class-workspace activity-work-part" data-work-key="${key}"${editable&&(hasEvidence||Object.values(notes).some(text=>text.trim())||state.drafts[evidenceDraftKey(unit)])?' open':''}><summary>Cuaderno web (opcional)</summary>${workNotice(editable)}<p class="caption">${editable?'Pregunta, explicación y revisión se guardan al escribir. Usa «Añadir evidencia» para guardar un fragmento nuevo.':'Continúa tu trabajo para editar.'}</p><details class="activity-work-part"${!hasEvidence||!notes.question?.trim()||state.drafts[evidenceDraftKey(unit)]?' open':''}><summary${phases?` id="cuaderno-${unit}-${phases[0]}"`:''}>Pregunta y evidencias</summary>${fichaQuestion(unit,state,editable)}${records(unit,state,editable,{section,review:unit===6})}</details><details class="activity-work-part"${hasEvidence&&!notes.revision?.trim()?' open':''}><summary${unit===3?' id="cuaderno-3-contexto"':unit===4?' id="cuaderno-4-argumento"':''}>Mi argumento</summary>${writing}</details><details class="activity-work-part"${notes.revision?.trim()?' open':''}><summary${phases?` id="cuaderno-${unit}-revision"`:''}>Mi revisión final</summary>${review}</details></details><p class="consult-links">En <a href="#cuaderno">Mi trabajo</a> puedes consultar y exportar lo que escribiste en el cuaderno web.</p></article>`;
 }
 function ficha(unit,state,editable,origin,section=null,returnPhase=null){
  const current=origin?.unit===unit?origin:classForWork({page:'ficha',unit,section});
  if(unit===2)return letterActivity(state,editable,current,returnPhase,section||fichaPhaseLinks[origin?.unit===2?origin.id:'']?.[0]);
  if(unit>1)return continuousActivity(unit,state,editable,current,section);
  return `<article class="class-page ficha-page"${unit>1?' data-simple-work':''}><div class="page-heading"><h1>Ficha ${unit} · ${esc(unitById[unit].title)}</h1><p>Empieza con la pregunta. Después guarda tus evidencias, escribe una explicación y revísala. Completa el paso que indique tu clase; esta misma ficha continúa durante la unidad.</p><p class="back-links"><a href="${classHref(current)}">Volver a la clase</a><a href="#cuaderno">Mi trabajo</a></p></div>${workNotice(editable)}${fichaQuestion(unit,state,editable)}${records(unit,state,editable)}${fichaFields(unit,state,editable,{all:true,includeQuestion:false})}${unit===5?relations(state,editable):''}</article>`;
 }
 function myWork(state,editable){
  return `<article class="class-page my-work"><div class="page-heading"><h1>Mi trabajo</h1><p>Este espacio reúne lo que escribes en el cuaderno web. Si trabajas en hojas, consérvalas juntas y llévalas a clase.</p><div class="actions">${continueLink(state)}</div></div><section class="work-collection"><h2>Diagnóstico inicial</h2><details><summary>Mi lectura y su revisión</summary>${noteFields(state,'apertura',['argument','revision','revisionReason'])||'<p>Todavía no has escrito el diagnóstico.</p>'}<p class="work-open">${state.notes.apertura?.argument?.trim()?'<a href="#semana/1/2">Continuar la revisión del diagnóstico</a>':'<a href="#semana/1/1">Abrir la clase del diagnóstico</a>'}</p></details><h2>Mis fichas</h2>${units.map(u=>`<details class="work-item"><summary>Ficha ${u.id} · ${esc(u.title)}<span class="work-state" data-work-status="ficha-${u.id}">${esc(workStatus(state,`ficha-${u.id}`))}</span></summary>${noteFields(state,`ficha-${u.id}`,u.id===2?[...letterFields,'question','argument','revision','revisionReason']:['question','argument','revision','revisionReason'])||'<p>Todavía no has escrito esta ficha.</p>'}${evidenceList(state,u.id,false)}<p class="work-open"><a href="#ficha/${u.id}">${u.id>1?'Continuar la actividad de la unidad '+u.id:'Abrir la ficha 1 para editarla'}</a></p></details>`).join('')}<h2>Expediente final</h2><a class="work-row" href="#proyecto"><span>Pregunta, corpus, método, análisis y revisión del mismo informe</span><span class="work-state" data-work-status="proyecto">${esc(workStatus(state,'proyecto'))}</span></a></section><section class="work-tools"><h2>Guardar y entregar</h2><p class="caption">Si usaste el cuaderno web, tu trabajo queda en este navegador. Puedes preparar el PDF o guardar un respaldo para continuar en otro equipo. La entrega se hace por el canal indicado por el docente.</p><div class="actions">${button('delivery','Preparar PDF de entrega')}${button('json','Descargar respaldo')}</div><details><summary>Más opciones</summary><div class="actions">${button('import','Recuperar respaldo')}${button('markdown','Exportar texto')}${button('lock','Ocultar mi trabajo')}</div><details><summary>Notas personales y acuerdos anteriores</summary>${['expectations','agreements','reflection'].map(name=>field(state,'apertura',name,fieldLabels[name],'Nota personal opcional.',3,editable)).join('')}</details>${state.relations.length?relations(state,editable):''}<details class="delete-zone"><summary>Limpiar este navegador</summary><p>Guarda antes un respaldo. El borrado requiere confirmación.</p>${button('clear','Borrar mi trabajo de este navegador')}</details></details></section></article>`;
 }
 return {index,classPage,ficha,myWork};
}


